#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch19: member page goes bilingual (default English, ?lang=ja for Japanese,
# toggle button in the header). Directory cards show the English name first
# with the Japanese name beside it. Site button in English mode says the
# target is Japanese before anyone clicks it.
# Default is dry-run. --apply writes. Anchors expect exactly 1 hit each.
# Pure ASCII file on purpose (macOS Python 3.9 tokenizer bug with long
# multibyte lines).
import sys, subprocess, tempfile, os, re

APPLY = "--apply" in sys.argv
EDITS = [('verify-directory/index.html', '      const nm = document.createElement("a"); nm.className = "regname";\n      nm.href = "member.html?endpoint=" + encodeURIComponent(r.endpoint);\n      nm.textContent = (r.operator_label && r.operator_label.ja) ? r.operator_label.ja : r.endpoint;\n      top.appendChild(nm);', '      const lb0 = r.operator_label || {};\n      const nm = document.createElement("a"); nm.className = "regname";\n      nm.href = "member.html?endpoint=" + encodeURIComponent(r.endpoint);\n      nm.textContent = lb0.en ? lb0.en : (lb0.ja ? lb0.ja : r.endpoint);\n      top.appendChild(nm);\n      if (lb0.en && lb0.ja){\n        top.appendChild(Object.assign(document.createElement("span"), { className: "regja", textContent: lb0.ja }));\n      }', 'card english primary'), ('verify-directory/index.html', 'a.regname:hover{border-bottom-style:solid}', 'a.regname:hover{border-bottom-style:solid}\n.regja{color:#9aa4b2;font-size:.8rem}', 'ja sub css')]
MEMBER_PATH = "verify-directory/member.html"
MEMBER_OLD_SHA_LEN = 7178
MEMBER_CONTENT = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Member page | HORIZON SHIELD verify directory</title>\n<style>\n:root{\n  --bg:#08080a; --bg-2:#0d0d10; --surface:#121216;\n  --line:rgba(255,255,255,.07); --line-2:rgba(255,255,255,.12);\n  --ink:#f4f4f5; --ink-2:#a9a9b3; --ink-3:#6f6f7a;\n  --mono:\'JetBrains Mono\',ui-monospace,SFMono-Regular,Menlo,monospace;\n  --sans:\'Inter\',system-ui,-apple-system,sans-serif;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:var(--bg);color:var(--ink);font-family:var(--sans);line-height:1.62;-webkit-font-smoothing:antialiased;\n  background-image:radial-gradient(900px 500px at 82% -8%,rgba(52,211,153,.10),transparent 60%);background-attachment:fixed}\n.wrap{max-width:860px;margin:0 auto;padding:0 26px}\na{color:inherit;text-decoration:none}\n.mono{font-family:var(--mono)}\nheader{position:sticky;top:0;background:rgba(8,8,10,.74);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}\n.bar{display:flex;align-items:center;justify-content:space-between;height:58px}\n.logo{font-weight:700;font-size:15px}\n.logo .sub{color:var(--ink-3);font-weight:500;font-size:11px;font-family:var(--mono)}\n.nav{display:flex;gap:18px;font-size:13.5px;color:var(--ink-2);align-items:center}\n.nav a:hover{color:var(--ink)}\n.langbtn{border:1px solid var(--line-2);border-radius:999px;padding:3px 12px;font-size:12px}\n.card{background:var(--surface);border:1px solid var(--line-2);border-radius:14px;padding:26px;margin:26px 0}\nh1{font-size:1.55rem;letter-spacing:-.02em}\n.sub2{color:var(--ink-2);margin-top:6px}\n.eprow{margin-top:12px;font-size:.8rem;color:var(--ink-3);word-break:break-all}\n.badge{display:inline-block;font-size:.78rem;padding:3px 12px;border-radius:999px;border:1px solid;margin-left:10px;vertical-align:middle}\n.b-pass{color:#7ee2a8;border-color:#2f6f4a}\n.b-pend{color:#e2c97e;border-color:#6f5c2f}\n.b-none{color:#9aa4b2;border-color:#3a4250}\n.sitelink{display:inline-block;margin-top:14px;border:1px solid var(--line-2);border-radius:8px;padding:7px 14px;font-size:.85rem;color:var(--ink-2)}\n.sitelink:hover{color:var(--ink);border-color:var(--ink-3)}\nh2{font-size:1.05rem;margin-bottom:10px}\ntable{width:100%;border-collapse:collapse;font-size:.83rem}\nth{color:var(--ink-3);font-weight:500;text-align:left}\nth,td{padding:8px 10px;border-bottom:1px solid var(--line)}\n.sha{font-family:var(--mono);font-size:.68rem;color:var(--ink-3);word-break:break-all}\n.note{color:var(--ink-2);font-size:.84rem;margin:8px 0}\n.cmd{background:var(--bg-2);border:1px solid var(--line);border-radius:8px;padding:12px 14px;font-family:var(--mono);font-size:.72rem;overflow-x:auto;white-space:pre;margin-top:8px}\nfooter{color:var(--ink-3);font-size:.78rem;padding:30px 0 50px}\n</style>\n</head>\n<body>\n<header><div class="wrap bar">\n  <div class="logo">HORIZON SHIELD <span class="sub">/ verify</span></div>\n  <div class="nav">\n    <a id="backlink" href="./">Back to the list</a>\n    <a id="langbtn" class="langbtn" href="#">\u65e5\u672c\u8a9e</a>\n  </div>\n</div></header>\n<section><div class="wrap">\n  <div id="content"><p class="note" style="margin-top:26px" id="loading">Loading\u2026</p></div>\n  <div class="card">\n    <h2 id="ph">What this page proves, and what it does not</h2>\n    <p class="note" id="p1"></p>\n    <p class="note" id="p2"></p>\n  </div>\n  <div class="card">\n    <h2 id="vh">Verify it yourself</h2>\n    <p class="note" id="vn"></p>\n    <div class="cmd" id="verifycmd"></div>\n  </div>\n  <footer class="wrap" style="padding-left:0">Public code: <a class="mono" href="https://github.com/ogasurfproject-jpg/horizon-shield" rel="noopener" style="color:var(--ink-2)">github.com/ogasurfproject-jpg/horizon-shield</a></footer>\n</div></section>\n<script>\nconst GATE = "https://gate.horizonshield.dev";\nconst qs = new URLSearchParams(location.search);\nconst LANG = qs.get("lang") === "ja" ? "ja" : "en";\nconst STR = {\n  en: {\n    back: "Back to the list",\n    langbtn: "\u65e5\u672c\u8a9e",\n    proveH: "What this page proves, and what it does not",\n    prove1: "The verdicts here are records of automated nightly measurement. Listing is not endorsement. Names and descriptions are display names assigned by the operator, not measurements. The register API carries the same note.",\n    prove2: "Every record_sha256 can be recomputed by anyone. The command below does exactly that. No trust in the operator is required.",\n    verifyH: "Verify it yourself",\n    verifyN: "One line in a terminal. Compare the hashes it returns with the hashes in the table above.",\n    histH: "Measurement history (newest first)",\n    cols: ["Measured at", "Verdict", "record_sha256"],\n    site: "Official site (Japanese)",\n    nfH: "This address is not on the register",\n    nfN: "Absence is not a negative verdict. It only means it has never been measured here.",\n    meas: function(n, first){ return n + " public measurements" + (first ? ", first on " + first : ""); },\n    none: "No stored measurements yet.",\n    noEp: "No endpoint specified. Come here by clicking a name on the list.",\n    fail: "The instrument could not read ({e}). No verdict is made. The register answers directly at " + GATE + "/register",\n    notyet: "not yet measured"\n  },\n  ja: {\n    back: "\u4e00\u89a7\u3078\u623b\u308b",\n    langbtn: "English",\n    proveH: "\u3053\u306e\u30da\u30fc\u30b8\u304c\u8a3c\u660e\u3059\u308b\u3053\u3068\u3001\u3057\u306a\u3044\u3053\u3068",\n    prove1: "\u3053\u3053\u306b\u4e26\u3076\u5224\u5b9a\u306f\u3001\u6bce\u6669\u306e\u81ea\u52d5\u6e2c\u5b9a\u306e\u8a18\u9332\u3060\u3002\u63b2\u8f09\u306f\u63a8\u85a6\u3067\u306f\u306a\u3044\u3002\u540d\u524d\u3068\u8aac\u660e\u306f\u904b\u55b6\u8005\u304c\u4ed8\u3051\u305f\u8868\u793a\u540d\u3067\u3042\u308a\u3001\u6e2c\u5b9a\u5024\u3067\u306f\u306a\u3044\u3002\u540c\u3058\u6ce8\u8a18\u306fregister API\u306e\u5fdc\u7b54\u306b\u3082\u66f8\u3044\u3066\u3042\u308b\u3002",\n    prove2: "\u5404\u884c\u306e record_sha256 \u306f\u8ab0\u3067\u3082\u518d\u8a08\u7b97\u3057\u3066\u7167\u5408\u3067\u304d\u308b\u3002\u4e0b\u306e\u691c\u8a3c\u30b3\u30de\u30f3\u30c9\u304c\u305d\u306e\u307e\u307e\u305d\u308c\u3092\u3084\u308b\u3002\u904b\u55b6\u8005\u3092\u4fe1\u7528\u3059\u308b\u5fc5\u8981\u306f\u306a\u3044\u3002",\n    verifyH: "\u81ea\u5206\u306e\u624b\u3067\u691c\u8a3c\u3059\u308b",\n    verifyN: "\u30bf\u30fc\u30df\u30ca\u30eb\u30671\u884c\u3002\u8fd4\u3063\u3066\u304d\u305f\u8a18\u9332\u306e\u30cf\u30c3\u30b7\u30e5\u3068\u3001\u4e0a\u306e\u8868\u306e\u30cf\u30c3\u30b7\u30e5\u304c\u4e00\u81f4\u3059\u308b\u304b\u3092\u898b\u308b\u3002",\n    histH: "\u6e2c\u5b9a\u5c65\u6b74\uff08\u65b0\u3057\u3044\u9806\uff09",\n    cols: ["\u6e2c\u5b9a\u65e5\u6642", "\u5224\u5b9a", "record_sha256"],\n    site: "\u516c\u5f0f\u30b5\u30a4\u30c8\u3092\u898b\u308b",\n    nfH: "\u3053\u306e\u4f4f\u6240\u306fregister\u306b\u7121\u3044",\n    nfN: "\u672a\u63b2\u8f09\u306f\u4e0d\u5408\u683c\u3067\u306f\u306a\u3044\u3002\u3053\u3053\u3067\u6e2c\u3089\u308c\u305f\u3053\u3068\u304c\u7121\u3044\u3001\u305d\u308c\u3060\u3051\u3092\u610f\u5473\u3059\u308b\u3002",\n    meas: function(n, first){ return "\u516c\u958b\u6e2c\u5b9a " + n + " \u56de" + (first ? "\u3001\u521d\u56de " + first : ""); },\n    none: "\u4fdd\u5b58\u3055\u308c\u305f\u6e2c\u5b9a\u306f\u307e\u3060\u7121\u3044\u3002",\n    noEp: "endpoint\u304c\u6307\u5b9a\u3055\u308c\u3066\u3044\u306a\u3044\u3002\u4e00\u89a7\u304b\u3089\u5e97\u540d\u3092\u30af\u30ea\u30c3\u30af\u3057\u3066\u6765\u3066\u304f\u308c\u3002",\n    fail: "\u8a08\u5668\u304c\u8aad\u3081\u306a\u304b\u3063\u305f\uff08{e}\uff09\u3002\u5224\u5b9a\u306f\u3057\u306a\u3044\u3002register\u306f " + GATE + "/register \u3067\u76f4\u63a5\u8aad\u3081\u308b\u3002",\n    notyet: "not yet measured"\n  }\n};\nconst T = STR[LANG];\nfunction el(tag, cls, text){\n  const e = document.createElement(tag);\n  if (cls) e.className = cls;\n  if (text !== undefined) e.textContent = text;\n  return e;\n}\nfunction badgeClass(stat){\n  return stat === "pass" ? "b-pass" : (stat === "pending" || stat === "held") ? "b-pend" : "b-none";\n}\nfunction setStatics(ep){\n  document.documentElement.lang = LANG;\n  document.getElementById("backlink").textContent = T.back;\n  const lb = document.getElementById("langbtn");\n  lb.textContent = T.langbtn;\n  const nq = new URLSearchParams(location.search);\n  if (LANG === "ja") nq.delete("lang"); else nq.set("lang", "ja");\n  lb.href = "member.html" + (nq.toString() ? "?" + nq.toString() : "");\n  document.getElementById("ph").textContent = T.proveH;\n  document.getElementById("p1").textContent = T.prove1;\n  document.getElementById("p2").textContent = T.prove2;\n  document.getElementById("vh").textContent = T.verifyH;\n  document.getElementById("vn").textContent = T.verifyN;\n  document.getElementById("verifycmd").textContent =\n    ep ? "curl -s \\"" + GATE + "/history?endpoint=" + encodeURIComponent(ep) + "\\"" : "curl -s \\"" + GATE + "/register\\"";\n}\nasync function main(){\n  const box = document.getElementById("content");\n  const ep = qs.get("endpoint");\n  setStatics(ep);\n  box.textContent = "";\n  if (!ep){\n    box.appendChild(el("p", "note", T.noEp));\n    return;\n  }\n  try {\n    const reg = await (await fetch(GATE + "/register")).json();\n    const row = (Array.isArray(reg.rows) ? reg.rows : []).find(function(r){ return r.endpoint === ep; });\n    const card = el("div", "card");\n    if (!row){\n      card.appendChild(el("h1", null, T.nfH));\n      card.appendChild(el("p", "note", T.nfN));\n      card.appendChild(el("p", "eprow mono", ep));\n      box.appendChild(card);\n      return;\n    }\n    const lb = row.operator_label || {};\n    const primary = LANG === "ja" ? (lb.ja || lb.en || row.endpoint) : (lb.en || lb.ja || row.endpoint);\n    const secondary = LANG === "ja" ? lb.en : lb.ja;\n    const h1 = el("h1", null, primary);\n    const stat = (row.latest && row.latest.status) ? row.latest.status : T.notyet;\n    h1.appendChild(el("span", "badge " + badgeClass(stat), stat));\n    card.appendChild(h1);\n    if (secondary && secondary !== primary) card.appendChild(el("p", "sub2", secondary));\n    card.appendChild(el("p", "eprow mono", row.endpoint));\n    if (typeof row.measurements === "number") card.appendChild(el("p", "note", T.meas(row.measurements, row.first_at ? String(row.first_at).slice(0,10) : "")));\n    if (lb.url){\n      const a = el("a", "sitelink", T.site);\n      a.href = lb.url; a.rel = "noopener";\n      card.appendChild(a);\n    }\n    box.appendChild(card);\n\n    const hcard = el("div", "card");\n    hcard.appendChild(el("h2", null, T.histH));\n    const hist = await (await fetch(GATE + "/history?endpoint=" + encodeURIComponent(ep))).json();\n    const entries = (hist && Array.isArray(hist.entries)) ? hist.entries.slice().reverse() : [];\n    if (!entries.length){\n      hcard.appendChild(el("p", "note", T.none));\n    } else {\n      const t = el("table");\n      const tr0 = el("tr");\n      T.cols.forEach(function(h){ tr0.appendChild(el("th", null, h)); });\n      t.appendChild(tr0);\n      entries.forEach(function(e2){\n        const tr = el("tr");\n        tr.appendChild(el("td", "mono", String(e2.at || "").replace("T", " ").slice(0, 19)));\n        const td = el("td");\n        td.appendChild(el("span", "badge " + badgeClass(e2.status || ""), e2.status || "?"));\n        tr.appendChild(td);\n        tr.appendChild(el("td", "sha", e2.record_sha256 || ""));\n        t.appendChild(tr);\n      });\n      hcard.appendChild(t);\n    }\n    box.appendChild(hcard);\n  } catch (err){\n    box.appendChild(el("p", "note", T.fail.replace("{e}", err.message)));\n  }\n}\ndocument.addEventListener("DOMContentLoaded", main);\n</script>\n</body>\n</html>\n'

def main():
    contents = {}
    ok = True
    for path, old, new, name in EDITS:
        if path not in contents:
            contents[path] = open(path, encoding="utf-8").read()
        n = contents[path].count(old)
        print("[anchor] %s: %d occurrence(s) (expect 1)" % (name, n))
        if n != 1: ok = False
    exists = os.path.exists(MEMBER_PATH)
    print("[anchor] member.html exists (v1 to replace): %s (expect yes)" % ("yes" if exists else "NO"))
    if not exists: ok = False
    else:
        cur = open(MEMBER_PATH, encoding="utf-8").read()
        isv1 = len(cur) == MEMBER_OLD_SHA_LEN
        print("[anchor] member.html length matches v1 (%d): %s" % (MEMBER_OLD_SHA_LEN, "yes" if isv1 else "NO, unexpected content"))
        if not isv1: ok = False
    if not ok:
        print("ABORT: anchor mismatch. Nothing written.")
        sys.exit(1)
    for path, old, new, name in EDITS:
        contents[path] = contents[path].replace(old, new, 1)

    p = contents["verify-directory/index.html"]
    checks = [
        (p.count("lb0.en") == 3, "page: english-first card name"),
        (p.count(".regja{") == 1, "page: ja sub css present"),
        ('"Official site (Japanese)"' in MEMBER_CONTENT, "member: honest site button label"),
        ("lang=ja" in MEMBER_CONTENT or 'nq.set("lang", "ja")' in MEMBER_CONTENT, "member: language toggle present"),
        ("What this page proves" in MEMBER_CONTENT, "member: english notes present"),
        ("\u63b2\u8f09\u306f\u63a8\u85a6\u3067\u306f\u306a\u3044" in MEMBER_CONTENT, "member: japanese notes present"),
    ]
    m = re.search(r"<script>(.*?)</script>", MEMBER_CONTENT, re.S)
    tf = tempfile.NamedTemporaryFile("w", suffix=".js", delete=False, encoding="utf-8"); tf.write(m.group(1)); tf.close()
    r = subprocess.run(["node", "--check", tf.name], capture_output=True, text=True)
    os.unlink(tf.name)
    checks.append((r.returncode == 0, "member: node --check ok" + ("" if r.returncode == 0 else " :: " + r.stderr.strip()[:200])))
    allok = True
    for good, label in checks:
        print(("[ok]  " if good else "[FAIL] ") + label)
        allok = allok and good
    if not allok:
        print("ABORT: invariant failed. Nothing written.")
        sys.exit(1)
    if not APPLY:
        print("DRY-RUN OK. Nothing written. Run with --apply to write.")
        return
    for path in contents:
        open(path, "w", encoding="utf-8").write(contents[path])
        print("[written] " + path)
    open(MEMBER_PATH, "w", encoding="utf-8").write(MEMBER_CONTENT)
    print("[written] " + MEMBER_PATH)
    print("APPLY done.")

if __name__ == "__main__":
    main()
